-- 0011_vehicle_reference_catalog: shared, read-only reference catalogue.
-- Built from CAR_RENTAL_Manager_Master_Data_V1_2.xlsx and PNEU_MOUHIM_Manager_Catalogue_Operations_V1_2.xlsx.
-- Contains reference data only: no customers, contracts, VINs, registrations or fleet records.
-- Source URLs are inert metadata; the application never fetches or previews them.
-- Compatibility records remain advisory and never authorize fitment without VIN/trim/door-label check.
-- No BEGIN/COMMIT here: the migration runner applies this file and records it in one transaction.
-- Corrections 2026-11-05 (review of PR #3), all derived from the data itself or the app's rules, nothing invented:
--   * commercial "C" tyre sizes: width / ratio / rim read from the size, reinforced = 'C';
--   * engines: power in kW computed from the published power in ch DIN (x 0.7355), noted in each row;
--   * oil brand "Huiles Lesieur/Local brands" removed (Lesieur is a food-oil company, not a motor-oil brand);
--     replaced by a placeholder for local brands to be named by the company;
--   * status reference completed with the six statuses the application enforces (vehicle_status_transitions);
--   * brand verification default aligned with the data ('À vérifier'); trailing space in an engine name removed.


CREATE TABLE vehicle_catalog_sources (
  id text PRIMARY KEY,
  publisher text NOT NULL,
  title text NOT NULL,
  source_type text,
  url text,
  source_date text,
  scope text,
  reliability text,
  notes text
);

CREATE TABLE vehicle_catalog_brands (
  id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  segment text,
  market_note text,
  verification_status text NOT NULL DEFAULT 'À vérifier'
);

CREATE TABLE vehicle_catalog_models (
  id text PRIMARY KEY,
  brand_id text NOT NULL REFERENCES vehicle_catalog_brands(id) ON DELETE RESTRICT,
  name text NOT NULL,
  data_status text,
  notes text,
  source_note text,
  start_year smallint,
  end_year smallint,
  body_type text,
  engine_descriptions text,
  generation_label text,
  engine_code text,
  fuel_type text,
  transmission text,
  power_kw numeric(8,2),
  displacement_cm3 integer,
  checked_on date,
  UNIQUE (brand_id, name)
);
CREATE INDEX vehicle_catalog_models_brand_idx ON vehicle_catalog_models(brand_id, name);

CREATE TABLE vehicle_catalog_generations (
  id text PRIMARY KEY,
  model_id text NOT NULL REFERENCES vehicle_catalog_models(id) ON DELETE RESTRICT,
  brand_id text NOT NULL REFERENCES vehicle_catalog_brands(id) ON DELETE RESTRICT,
  label text NOT NULL,
  generation_code text,
  production_start_year smallint,
  production_end_year smallint,
  reference_year smallint,
  body_type text,
  market text,
  source_id text REFERENCES vehicle_catalog_sources(id) ON DELETE RESTRICT,
  source_url text,
  verification_status text NOT NULL,
  notes text
);

CREATE TABLE vehicle_catalog_engines (
  id text PRIMARY KEY,
  generation_id text NOT NULL REFERENCES vehicle_catalog_generations(id) ON DELETE RESTRICT,
  commercial_version text NOT NULL,
  engine_designation text,
  engine_code text,
  displacement_cm3 integer,
  cylinders smallint,
  fuel_type text,
  power_hp numeric(8,2),
  power_kw numeric(8,2),
  torque_nm numeric(8,2),
  gearbox text,
  gears smallint,
  source_id text REFERENCES vehicle_catalog_sources(id) ON DELETE RESTRICT,
  verification_status text NOT NULL,
  notes text
);

CREATE TABLE vehicle_catalog_tire_brands (
  id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  origin text,
  positioning text,
  availability text
);
CREATE TABLE vehicle_catalog_tire_models (
  id text PRIMARY KEY,
  brand_id text NOT NULL REFERENCES vehicle_catalog_tire_brands(id) ON DELETE RESTRICT,
  name text NOT NULL,
  vehicle_type text,
  season text,
  usage text,
  verification text,
  UNIQUE (brand_id, name)
);
CREATE TABLE vehicle_catalog_tire_sizes (
  size text PRIMARY KEY,
  width_mm integer,
  aspect_ratio integer,
  rim_inches integer,
  load_index text,
  speed_index text,
  reinforced text,
  run_flat text,
  compatibility_status text NOT NULL,
  note text
);
CREATE TABLE vehicle_catalog_tire_fitments (
  id text PRIMARY KEY,
  generation_id text NOT NULL REFERENCES vehicle_catalog_generations(id) ON DELETE RESTRICT,
  engine_id text REFERENCES vehicle_catalog_engines(id) ON DELETE RESTRICT,
  trim text,
  position text,
  dimension text NOT NULL REFERENCES vehicle_catalog_tire_sizes(size) ON DELETE RESTRICT,
  load_index text,
  speed_index text,
  reinforced text,
  run_flat text,
  compatibility_type text,
  source_id text REFERENCES vehicle_catalog_sources(id) ON DELETE RESTRICT,
  source_url text,
  checked_on date,
  verification_status text NOT NULL,
  notes text
);

CREATE TABLE vehicle_catalog_oil_brands (
  id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  origin text,
  availability text
);
CREATE TABLE vehicle_catalog_oil_products (
  id text PRIMARY KEY,
  brand_id text NOT NULL REFERENCES vehicle_catalog_oil_brands(id) ON DELETE RESTRICT,
  name text NOT NULL,
  indicative_viscosity text,
  technology text,
  usage text,
  verification text,
  acea text,
  api text,
  oem_approval text,
  packaging text,
  item_reference text,
  technical_sheet_source text,
  final_status text,
  UNIQUE (brand_id, name, indicative_viscosity)
);
CREATE TABLE vehicle_catalog_oil_fitments (
  id text PRIMARY KEY,
  generation_id text NOT NULL REFERENCES vehicle_catalog_generations(id) ON DELETE RESTRICT,
  engine_id text NOT NULL REFERENCES vehicle_catalog_engines(id) ON DELETE RESTRICT,
  engine_version text,
  sae_viscosity text,
  acea text,
  api text,
  oem_approval text,
  capacity_l numeric(8,2),
  oil_filter_ref text,
  source_id text REFERENCES vehicle_catalog_sources(id) ON DELETE RESTRICT,
  verification_status text NOT NULL,
  notes text
);

CREATE TABLE vehicle_catalog_maintenance (
  id text PRIMARY KEY,
  name text NOT NULL,
  examples text,
  interval_guidance text,
  source_status text
);
CREATE TABLE vehicle_catalog_market_priority (
  priority_rank integer NOT NULL,
  brand_id text NOT NULL REFERENCES vehicle_catalog_brands(id) ON DELETE RESTRICT,
  model_id text NOT NULL REFERENCES vehicle_catalog_models(id) ON DELETE RESTRICT,
  registrations integer,
  market_share_pct numeric(8,3),
  period text NOT NULL,
  source_id text REFERENCES vehicle_catalog_sources(id) ON DELETE RESTRICT,
  notes text,
  PRIMARY KEY (period, priority_rank)
);
CREATE TABLE vehicle_catalog_status_reference (
  code text PRIMARY KEY,
  app_status text NOT NULL UNIQUE
             CHECK (app_status IN ('available', 'rented', 'inspection_pending', 'maintenance', 'out_of_service', 'retired')),
  label text NOT NULL,
  trigger_description text,
  blocks_rental boolean,
  expected_action text,
  exit_rule text
);

ALTER TABLE vehicles
  ADD COLUMN catalog_model_id text REFERENCES vehicle_catalog_models(id) ON DELETE RESTRICT,
  ADD COLUMN catalog_generation_id text REFERENCES vehicle_catalog_generations(id) ON DELETE RESTRICT,
  ADD COLUMN catalog_engine_id text REFERENCES vehicle_catalog_engines(id) ON DELETE RESTRICT;
CREATE INDEX vehicles_catalog_model_idx ON vehicles(catalog_model_id) WHERE catalog_model_id IS NOT NULL;

