INSERT INTO vehicle_catalog_engines (id, generation_id, commercial_version, engine_designation, engine_code, displacement_cm3, cylinders, fuel_type, power_hp, power_kw, torque_nm, gearbox, gears, source_id, verification_status, notes) VALUES ('ENG-DAC-LOG-TCE100-BVM', 'GEN-DAC-LOG-CUR', 'TCe 100', 'TCe 100 (1.0 L)', NULL, NULL, NULL, 'Essence', 100, 73.5, NULL, 'Manuelle', 5, 'DAC-LOG-MOTOR', 'OFFICIAL_LINEUP_PARTIAL', 'La fiche Dacia Maroc indique TCe 100, essence, moteur 1.0 L, 100 ch et boîte manuelle; code moteur/cylindrée exacte à obtenir via VIN ou documentation atelier. Puissance kW calculée depuis 100 ch DIN (× 0,7355) = 73,5 kW.') ;
INSERT INTO vehicle_catalog_engines (id, generation_id, commercial_version, engine_designation, engine_code, displacement_cm3, cylinders, fuel_type, power_hp, power_kw, torque_nm, gearbox, gears, source_id, verification_status, notes) VALUES ('ENG-DAC-LOG-DCI95', 'GEN-DAC-LOG-CUR', 'dCi 95', 'dCi 95', NULL, NULL, NULL, 'Diesel', 95, 69.9, NULL, 'Manuelle', NULL, 'DAC-LOG-MOTOR', 'OFFICIAL_LINEUP_PARTIAL', 'La fiche Dacia Maroc indique dCi 95 diesel 95 ch et boîte manuelle; cylindrée, code moteur et rapport de boîte exacts non indiqués dans la page consultée. Puissance kW calculée depuis 95 ch DIN (× 0,7355) = 69,9 kW.') ;
