INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('AVAILABLE', 'available', 'Disponible', 'Inspection validée, ou véhicule prêt à l''agence', FALSE, 'Peut être réservé et remis au client.', 'Départ (contrat) → En location; ou Maintenance / Bloqué avec motif.') ;
INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('RENTED', 'rented', 'En location', 'Remise du véhicule au client (départ du contrat)', TRUE, 'Suivre la date de retour prévue et les retards.', 'Retour du véhicule → À inspecter.') ;
INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('TO_INSPECT', 'inspection_pending', 'À inspecter', 'Après retour / réception du véhicule', TRUE, 'Contrôle visuel, kilométrage, carburant, photos et dégâts; consigner les anomalies.', 'Passer à Disponible après validation; ou Maintenance / Hors service selon constat.') ;
INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('MAINTENANCE', 'maintenance', 'En maintenance', 'Inspection avec défaut, ou entretien planifié (motif obligatoire)', TRUE, 'Réparation ou entretien au garage; enregistrer le coût.', 'Réparation terminée → À inspecter; ou Bloqué avec motif.') ;
INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('OUT_OF_SERVICE', 'out_of_service', 'Bloqué', 'Décision du gérant (motif obligatoire)', TRUE, 'Le véhicule ne peut pas être loué.', 'Débloquer → À inspecter; ou Retirer de la flotte (définitif).') ;
INSERT INTO vehicle_catalog_status_reference (code, app_status, label, trigger_description, blocks_rental, expected_action, exit_rule) VALUES ('RETIRED', 'retired', 'Retiré', 'Vendu ou sorti de la flotte (décision du gérant, motif obligatoire)', TRUE, 'Conservé pour l''historique; plus aucune location.', 'Définitif.') ;
